fn documented_name_renames_memory_locations() {
    let mut engine = Engine::default();
    let first = engine.execute("markers.add", &json!({"name": "Verse", "at": 1000})).unwrap();
    let second = engine.execute("markers.add", &json!({"name": "Outro", "at": 3000})).unwrap();
