    engine.execute("event.tempo", &json!({"bpm": 140.0, "at": 48_000})).unwrap();
    let result = engine.execute(
        "event.tempo_constant",
        &json!({"bpm": 90.0, "start": 0, "end": 96_000}),
    ).unwrap();
    let session = engine.session();
    let tick = session.tempo.samples_to_ticks(72_000, session.sample_rate);
    let actual = session.tempo.tempo_at_tick(tick);
    println!("result={result}, tick={tick}, bpm={actual}");
    assert_eq!(actual, 90.0);
}

